            cycle: CYCLE.TWO_YEARS,
            planIDs: {
                [PLANS.MAIL_PRO]: 1,
                [ADDON_NAMES.MEMBER_MAIL_PRO]: 4,
                [ADDON_NAMES.IP_VPN_BUSINESS]: 2,
                [ADDON_NAMES.MEMBER_SCRIBE_MAIL_PRO]: 2,
            },
            maximumCycle: CYCLE.TWO_YEARS,
            minimumCycle: CYCLE.TWO_YEARS,
            withB2CAddons: true,
